SELECT id, project_id, deliverable_code, name, stage_code, task_code, required,
       source_definition_id, status, version,
       creator, create_time, updater, update_time, deleted, tenant_id
FROM acc_project_deliverable
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND deliverable_code = #{query.deliverableCode}
  AND deleted = 0
FOR UPDATE
